const source="// Internal callback SLA only. No messaging provider is called by this code.\nconst policy={\"version\":\"2026-10-20\",\"approvedByOwnerInChat\":true,\"scope\":\"intake, questionnaire, CRM documentation, response, appointment coordination\",\"owner\":\"yoram\",\"customerContactPhone\":\"excelent_contact\",\"timezone\":\"Asia/Jerusalem\",\"businessHours\":{\"days\":[0,1,2,3,4],\"open\":\"08:30\",\"close\":\"20:00\"},\"responseMinutes\":{\"questionnaireSubmittedWithKnownAnswers\":30,\"withoutQuestionnaire\":60},\"outsideBusinessHours\":\"next_business_day\",\"holidayCalendar\":null,\"activationStatus\":\"callback_delivery_not_verified_in_live_operations_see_release_report_for_deployment\",\"testMessaging\":{\"allowedRecipientPhone\":\"yoram_050\",\"allowedE164\":\"972502234052\",\"purpose\":\"internal acceptance tests only\",\"realCustomersAllowed\":false,\"groupsAllowed\":false},\"deferred\":[\"SMS\",\"email nurturing\",\"WhatsApp tips group\"],\"notes\":[\"Questionnaire answers may include unknown or skipped details; do not demand financial documents before returning to the lead.\",\"This file records owner decisions. See the release report for the deployed reminder version; a callback or appointment still requires operational evidence.\",\"Business hours count in Israel time; advertising account schedules currently display PDT.\",\"Do not silently reuse the existing 45-minute reminder as proof of the new 30/60-minute SLA.\"]};\nconst quizPattern=new RegExp(\"(?:^|\\\\n)(?:יש לכם היום משכנתא|מה המטרה העיקרית|מה יתרת המשכנתא בקירוב|מה ההחזר החודשי היום|כמה זמן נשאר לתשלום|מתי תרצו לפעול|מה אתם מבקשים כרגע|יש לכם דוח יתרות לסילוק עדכני|יש הלוואות נוספות מלבד המשכנתא|צפוי שינוי בהכנסה בשנים הקרובות|מתוכננים מכירה של הנכס או פירעון גדול|יש קושי בתשלומים היום)\\\\? .+\");\nconst response=$input.first().json;\nconst page=response.data?.boards?.[0]?.groups?.[0]?.items_page;\nif(response.errors?.length||!Array.isArray(page?.items)||page.cursor)throw Error('Incomplete Monday SLA lookup');\nconst sd=$getWorkflowStaticData('global'),now=Date.now();\nconst fmt=new Intl.DateTimeFormat('en-GB',{timeZone:policy.timezone,weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false});\nconst days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];\nconst mins=s=>{const [h,m]=s.split(':').map(Number);return h*60+m;};\nfunction open(t){const p={};fmt.formatToParts(new Date(t)).forEach(x=>p[x.type]=x.value);const m=(+p.hour%24)*60+(+p.minute);return policy.businessHours.days.includes(days.indexOf(p.weekday))&&m>=mins(policy.businessHours.open)&&m<mins(policy.businessHours.close);}\nif(!open(now))return [];\nfunction elapsed(from,to,cap){let total=0;for(let t=from;t<to&&total<cap;){const end=Math.min(to,(Math.floor(t/60000)+1)*60000);if(open(t))total+=end-t;t=end;}return total;}\nconst out=[];\nfor(const it of page.items){\n const cv=Object.fromEntries((it.column_values||[]).map(c=>[c.id,c]));\n const text=id=>cv[id]?.text||'';\n if(!/LP1|מטא|וואטסאפ/i.test(text('refi_source')))continue;\n if(!['ליד חדש','התקבל',''].includes(text('refi_stage'))||text('refi_first_reply').trim())continue;\n let requested=Date.parse(it.created_at);\n try{const d=JSON.parse(cv.date_mm88hmw2?.value||'null');if(d?.date)requested=Date.parse(d.date+'T'+(d.time||'00:00:00')+'Z');}catch(e){continue;}\n if(!Number.isFinite(requested)||requested>now||now-requested>3*86400000)continue;\n const questionnaire=quizPattern.test(text('long_text_mm88xzfe'));\n const limit=questionnaire?policy.responseMinutes.questionnaireSubmittedWithKnownAnswers:policy.responseMinutes.withoutQuestionnaire;\n const key=String(it.id)+':'+requested+':'+limit;\n if(sd.reminded?.[key]||Number(sd.reminded?.[it.id]||0)>=requested)continue;\n if(elapsed(requested,now,limit*60000)<limit*60000)continue;\n out.push({json:{item:String(it.id),reminderKey:key,requestedAt:requested,thresholdMinutes:limit,questionnaire,leadName:it.name,source:text('refi_source'),phone:text('refi_phone'),text:`תזכורת ליורם פלד: פנייה ${it.id} טרם טופלה לאחר ${limit} דקות פעילות (${questionnaire?'נשלחו תשובות שאלון':'ללא תשובות שאלון'}). שעות הפעילות א׳–ה׳ 08:30–20:00.`}});\n}\n// Cache acknowledgment belongs after confirmed internal notification, never here.\nreturn out;\n",ack="// Per-item acknowledgment of a confirmed Monday internal notification.\nconst planned=$('Pick overdue').item.json;\nif($json.errors?.length||!$json.data?.create_notification?.text)throw Error('Internal notification not confirmed; keep eligible for retry');\nif(!planned.item||!planned.reminderKey)throw Error('Missing reminder ownership');\nconst sd=$getWorkflowStaticData('global');sd.reminded=sd.reminded||{};\nsd.reminded[planned.reminderKey]=Date.now();\nfor(const [k,t]of Object.entries(sd.reminded))if(Date.now()-Number(t)>7*86400000)delete sd.reminded[k];\nreturn {json:{...planned,notificationConfirmed:true}};\n";
const lead=(created,extra={})=>({id:'1',name:'TEST SLA',created_at:created,column_values:Object.entries({refi_source:'קליטת LP1',refi_stage:'ליד חדש',...extra}).map(([id,v])=>({id,text:typeof v==='string'?v:'',value:typeof v==='string'?null:JSON.stringify(v)}))});
function run(now,items,store={},override){const date=class extends Date{constructor(...a){super(...(a.length?a:[now]));}static now(){return Date.parse(now);}};return new Function('$input','$getWorkflowStaticData','Date',source)({first:()=>({json:override||{data:{boards:[{groups:[{items_page:{items,cursor:null}}]}]}}})},()=>store,date).map(x=>x.json);}
