test('SLA handled, replied, future and stale leads do not alert',()=>{const now='2026-10-20T09:00:00Z';for(const l of [lead('2026-10-20T06:00:00Z',{refi_stage:'בטיפול'}),lead('2026-10-20T06:00:00Z',{refi_first_reply:'2026-10-20'}),lead('2026-10-21T06:00:00Z'),lead('2026-10-01T06:00:00Z')])assert.equal(run(now,[l]).length,0);});
test('SLA new service request resets elapsed time for a repeated submission',()=>{const l=lead('2026-10-20T06:00:00Z',{...quiz,date_mm88hmw2:{date:'2026-10-20',time:'08:45:00'}});assert.equal(run('2026-10-20T09:00:00Z',[l]).length,0);});
test('SLA incomplete lookup fails closed and planning does not mark delivery',()=>{for(const r of [{errors:[{message:'down'}]},{data:{boards:[{groups:[{items_page:{items:[],cursor:'more'}}]}]}}])assert.throws(()=>run('2026-10-20T09:00:00Z',[],{},r),/Incomplete/);const sd={},p=run('2026-10-20T09:00:00Z',[lead('2026-10-20T06:00:00Z')],sd);assert.equal(p.length,1);assert.deepEqual(sd,{});});
